"""The replay file (.fzrp): its constants, the version a race's features make, and a file's parts as far as
the file has them (parse, read). Every number big-endian. It judges nothing: what a tool refuses is its own
(protocol/formats.md section 1)."""
import lzma
import struct

MARK = b"FZRP"
FRAMES_MARK = b"FZRF"
LINEUP_MARK = b"FZRL"
RESULTS_MARK = b"FZRS"
VERSION_PLAIN = 2  # a race of the disc's own car data and none of the features below
VERSION_STATS = 3  # the race ran on a stat pack (the header's match.setup.stats)
VERSION_CUSTOM = 4  # a seat raced a custom machine (a seat's match.setup.seats[].custom)
VERSION_MINES = 5  # the race's mines came back (match.setup.rules.mineRegenMs gives a step or more)
VERSION_SEATS = 6  # a seat raced a pack of its own (match.setup.packs, a seat's pack)
VERSION_GRID = 7  # 0.4.0's set-up: the race started on the coordinator's grid (match.setup.grid) or raced wit
COMPACT_VERSION = 8  # the compact file a recording becomes when it ends
HEADER_MARK = b"FZRH"
INPUTS_MARK = b"FZRI"
CHECKSUMS_MARK = b"FZRC"
FULL_EVERY = 60
XZ_PRESET = 9
DICT_MIN = 4096
DICT_MAX = 67108864
XZ_MEMLIMIT = 134217728
MAX_JSON = 1048576
VERSION_WRITTEN = 7
VERSIONS = (2, 3, 4, 5, 6, 7)
FEATURES = ("stats", "custom", "mines", "seat_packs", "grid")
HEAD_SIZE = 10
FRAMES_SIZE = 12
LINEUP_SIZE = 124
LINEUP_LEAST = 122
RECORD_SIZE = 6
CHECKSUM_SIZE = 4
RESULTS_TAIL = 8
MAX_BYTES = 268435456
MAX_STEPS = 1296000
MAX_SEATS = 30
HEADER_KEYS = ("match", "seat", "mask", "delay", "flow", "rubberBand", "simGenerator", "mod_sha1", "mod_commit", "game", "engine", "module_sha1", "recorded", "practice")
RESULT_KEYS = ("seat", "rank", "finished", "out", "laps", "timeMs", "bestLapMs")
# the lineup's block: (name, offset, count, struct format of one)
LINEUP_FIELDS = (("machines", 0, 30, "B"), ("ranks", 30, 30, "B"), ("settings", 60, 30, "h"), ("control_mode", 120, 1, "B"), ("rel_d70", 121, 1, "B"),)


def played(version):
    """Whether the game plays a file of this version."""
    return version in VERSIONS or version == COMPACT_VERSION


def version_of(**features):
    """The version a race of these features (FEATURES: True or False) is, and the only one its file may be: the
    highest whose feature it holds, else the first."""
    unknown = set(features) - set(FEATURES)
    if unknown:
        raise ValueError(f"no feature {sorted(unknown)}")
    if features.get("grid"):
        return VERSION_GRID
    if features.get("seat_packs"):
        return VERSION_SEATS
    if features.get("mines"):
        return VERSION_MINES
    if features.get("custom"):
        return VERSION_CUSTOM
    if features.get("stats"):
        return VERSION_STATS
    return VERSION_PLAIN


def lineup(block):
    """The lineup's block as a dict of its fields (a block shorter than LINEUP_SIZE reads 0 after its end)."""
    b = bytes(block[:LINEUP_SIZE]).ljust(LINEUP_SIZE, b"\0")
    out = {}
    for name, at, count, one in LINEUP_FIELDS:
        values = struct.unpack_from(f">{count}{one}", b, at)
        out[name] = list(values) if count > 1 else values[0]
    return out


class Replay:
    """A file's parts, as far as the file has them (each read only when the one before it is whole). header and
    results are the JSON's bytes (None: not in the file); lineup is the block's bytes and lineup_part the bytes
    from the frames' part to the first step; steps is [(the seats' records, the checksum's 4 bytes)] of the
    whole steps; whole says the steps' bytes are whole steps."""

    def __init__(self):
        self.marked, self.version, self.header_length, self.header = False, 0, 0, None
        self.frames, self.frames_marked, self.mask, self.seat, self.seats = False, False, 0, 0, []
        self.has_lineup, self.lineup_length, self.lineup, self.lineup_part = False, 0, b"", b""
        self.results, self.steps_at, self.steps_end, self.steps, self.whole = None, 0, 0, [], False
        self.race_version, self.compact, self.error = 0, False, None


def parse(data):
    """A replay file's bytes, in their parts (Replay). A compact file is read as the file it was made of
    (expand): version and compact say it, race_version is its race's; one that does not read has marked,
    version and error alone."""
    if len(data) >= 6 and data[:4] == MARK and struct.unpack_from(">H", data, 4)[0] == COMPACT_VERSION:
        try:
            r = parse(expand(data))
        except ValueError as e:
            r = Replay()
            r.marked, r.error = True, str(e)
        r.version, r.compact = COMPACT_VERSION, True
        r.race_version = r.race_version if r.error is None else 0
        n = len(r.steps)
        r.steps = [(row, Checksum(c, is_full(t, n))) for t, (row, c) in enumerate(r.steps)]
        return r
    r = Replay()
    if len(data) < HEAD_SIZE or data[:4] != MARK:
        return r
    r.marked = True
    r.version, r.header_length = struct.unpack_from(">HI", data, 4)
    r.race_version = r.version
    frames_at = HEAD_SIZE + r.header_length
    if frames_at > len(data):
        return r
    r.header = bytes(data[HEAD_SIZE:frames_at])
    if len(data) - frames_at < FRAMES_SIZE:
        return r
    r.frames, r.frames_marked = True, data[frames_at:frames_at + 4] == FRAMES_MARK
    r.mask, r.seat = struct.unpack_from(">II", data, frames_at + 4)
    r.seats = [i for i in range(32) if r.mask >> i & 1]
    frames_end = frames_at + FRAMES_SIZE
    r.steps_at, r.steps_end = frames_end, len(data)
    if len(data) - frames_end >= RESULTS_TAIL and data[-4:] == RESULTS_MARK:
        length = struct.unpack_from(">I", data, len(data) - 8)[0]
        if length + RESULTS_TAIL <= len(data) - frames_end:
            r.steps_end = len(data) - RESULTS_TAIL - length
            r.results = bytes(data[r.steps_end:len(data) - RESULTS_TAIL])
    if r.steps_end - frames_end >= 8 and data[frames_end:frames_end + 4] == LINEUP_MARK:
        r.has_lineup = True
        r.lineup_length = struct.unpack_from(">I", data, frames_end + 4)[0]
        r.steps_at = frames_end + 8 + r.lineup_length
        r.lineup = bytes(data[frames_end + 8:min(r.steps_at, r.steps_end)])
    r.lineup_part = bytes(data[frames_end:min(r.steps_at, r.steps_end)])
    row = len(r.seats) * RECORD_SIZE
    size = row + CHECKSUM_SIZE
    if r.seats and r.steps_end >= r.steps_at:
        r.steps = [(bytes(data[at:at + row]), Checksum(data[at + row:at + size]))
                   for at in range(r.steps_at, r.steps_end - size + 1, size)]
        r.whole = (r.steps_end - r.steps_at) % size == 0
    return r



def fold(checksum):
    """A step's checksum as the compact file keeps it between its whole ones: its four bytes XORed."""
    return (checksum ^ checksum >> 8 ^ checksum >> 16 ^ checksum >> 24) & 0xFF


def is_full(step, steps):
    """Whether a compact file of `steps` steps keeps step's whole checksum: every FULL_EVERY-th and the last."""
    return step % FULL_EVERY == 0 or step == steps - 1


class Checksum(bytes):
    """A step's checksum, its four bytes; full says the file holds it whole (a compact file's other steps hold the
    folded byte, as 0, 0, 0, the byte). Two are equal when both are whole and the same, or else when their folded
    bytes are: so a compact file compares with a whole one, or with another compact one, at every step."""

    def __new__(cls, four, full=True):
        c = super().__new__(cls, bytes(four))
        c.full = full
        return c

    def value(self):
        return int.from_bytes(self, "big")

    def __eq__(self, other):
        if not isinstance(other, (bytes, bytearray)) or len(other) != len(self):
            return NotImplemented
        if self.full and getattr(other, "full", True):
            return bytes(self) == bytes(other)
        return fold(self.value()) == fold(int.from_bytes(other, "big"))

    def __ne__(self, other):
        equal = self.__eq__(other)
        return equal if equal is NotImplemented else not equal

    def __hash__(self):
        return hash(fold(self.value()))


def xz(data):
    """data as the compact file's xz stream: LZMA2 at XZ_PRESET with the extreme flag, the dictionary data's size."""
    size = min(max(len(data), DICT_MIN), DICT_MAX)
    return lzma.compress(data, format=lzma.FORMAT_XZ, check=lzma.CHECK_CRC32,
                         filters=[{"id": lzma.FILTER_LZMA2, "preset": XZ_PRESET | lzma.PRESET_EXTREME, "dict_size": size}])


def unxz(data, most, exact=False):
    """One xz stream, whole and checked, of at most `most` bytes (exactly `most` with exact); else ValueError."""
    d = lzma.LZMADecompressor(format=lzma.FORMAT_XZ, memlimit=XZ_MEMLIMIT)
    try:
        out = d.decompress(bytes(data), max_length=most + 1)
    except lzma.LZMAError as e:
        raise ValueError(f"an xz part does not read: {e}") from None
    if not d.eof or d.unused_data or len(out) > most or (exact and len(out) != most):
        raise ValueError("an xz part is cut, longer than its part, or followed by other bytes")
    return out


def _section(mark, body):
    return mark + struct.pack(">I", len(body)) + body


def compact(data):
    """A whole recording of a version the game plays (VERSIONS: header, frames, lineup, whole steps, results or
    none) as the compact file; ValueError for any other."""
    r = parse(data)
    if not r.marked or r.version not in VERSIONS or r.header is None or not r.frames_marked or not r.has_lineup \
            or r.lineup_length != LINEUP_SIZE or not r.steps or not r.whole:
        raise ValueError("not a whole recording")
    n, width = len(r.steps), len(r.seats) * RECORD_SIZE
    rows = b"".join(row for row, _ in r.steps)
    planes = b"".join(rows[j::width] for j in range(width))
    sums = [c.value() for _, c in r.steps]
    checks = bytes(fold(c) for c in sums) + b"".join(struct.pack(">I", sums[t]) for t in range(n) if is_full(t, n))
    out = MARK + struct.pack(">HH", COMPACT_VERSION, r.version) + _section(HEADER_MARK, xz(r.header))
    out += _section(FRAMES_MARK, struct.pack(">II", r.mask, r.seat)) + _section(LINEUP_MARK, r.lineup)
    out += _section(INPUTS_MARK, struct.pack(">I", n) + xz(planes)) + _section(CHECKSUMS_MARK, xz(checks))
    if r.results is not None:
        out += r.results + struct.pack(">I", len(r.results)) + RESULTS_MARK
    return out


def expand(data):
    """A compact file as the recording it was made of, but that a step whose whole checksum
    the compact file does not keep holds its folded byte (0, 0, 0, the byte); ValueError for a file that is not one."""
    data = bytes(data)
    if len(data) < 8 or data[:4] != MARK or struct.unpack_from(">H", data, 4)[0] != COMPACT_VERSION:
        raise ValueError("not a compact replay")
    race = struct.unpack_from(">H", data, 6)[0]
    if race not in VERSIONS:
        raise ValueError(f"a recording of version {race}, which the game does not play")
    if len(data) > MAX_BYTES:
        raise ValueError("longer than MAX_BYTES")
    end, results = len(data), b""
    if end - 8 >= RESULTS_TAIL and data[-4:] == RESULTS_MARK:
        length = struct.unpack_from(">I", data, end - 8)[0]
        if length + RESULTS_TAIL <= end - 8:
            end -= RESULTS_TAIL + length
            results = data[end:]
    at, parts = 8, []
    for mark in (HEADER_MARK, FRAMES_MARK, LINEUP_MARK, INPUTS_MARK, CHECKSUMS_MARK):
        if end - at < 8 or data[at:at + 4] != mark:
            raise ValueError(f"no {mark.decode()} part where it belongs")
        length = struct.unpack_from(">I", data, at + 4)[0]
        if length > end - at - 8:
            raise ValueError(f"the {mark.decode()} part ends after the file")
        parts.append(data[at + 8:at + 8 + length])
        at += 8 + length
    if at != end:
        raise ValueError("bytes between the parts and the results")
    header_xz, frames, lineup, inputs, checks_xz = parts
    header = unxz(header_xz, MAX_JSON)
    if len(frames) != FRAMES_SIZE - 4 or len(inputs) < 4:
        raise ValueError("a frames or inputs part of another size")
    mask, seat = struct.unpack(">II", frames)
    n = struct.unpack_from(">I", inputs)[0]
    width = bin(mask).count("1") * RECORD_SIZE
    if width == 0 or not 0 < n <= MAX_STEPS:
        raise ValueError("no player seat, or no step, or more than MAX_STEPS")
    planes = unxz(inputs[4:], n * width, exact=True)
    full = [t for t in range(n) if is_full(t, n)]
    checks = unxz(checks_xz, n + 4 * len(full), exact=True)
    rows = bytearray(n * width)
    for j in range(width):
        rows[j::width] = planes[j * n:(j + 1) * n]
    sums = [bytes((0, 0, 0, b)) for b in checks[:n]]
    for k, t in enumerate(full):
        whole = checks[n + 4 * k:n + 4 * k + 4]
        if fold(int.from_bytes(whole, "big")) != checks[t]:
            raise ValueError(f"step {t}'s whole checksum and its byte disagree")
        sums[t] = whole
    out = bytearray(MARK + struct.pack(">HI", race, len(header)) + header)
    out += FRAMES_MARK + frames + LINEUP_MARK + struct.pack(">I", len(lineup)) + lineup
    for t in range(n):
        out += rows[t * width:(t + 1) * width] + sums[t]
    return bytes(out + results)


def read(path):
    """The replay file at path, in its parts (Replay)."""
    with open(path, "rb") as f:
        return parse(f.read())
